{"command":"cat << 'EOF' > mylz4.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define HASH_BITS 16
#define HASH_SIZE (1 << HASH_BITS)
#define MIN_MATCH 4
#define MAX_DISTANCE 65535

uint32_t hash(const uint8_t* p) {
    uint32_t val;
    memcpy(&val, p, 4);
    return (val * 2654435761u) >> (32 - HASH_BITS);
}

int compress_block(const uint8_t* in, int in_len, uint8_t* out) {
    if (in_len < MIN_MATCH) return 0; // fallback to uncompressed

    int table[HASH_SIZE];
    for(int i=0; i<HASH_SIZE; i++) table[i] = -1;

    int op = 0;
    int ip = 0;
    int anchor = 0;

    while (ip < in_len - 12) {
        uint32_t h = hash(in + ip);
        int ref = table[h];
        table[h] = ip;

        if (ref >= 0 && ip - ref <= MAX_DISTANCE && memcmp(in + ref, in + ip, 4) == 0) {
            // Match found!
            int match_len = 4;
            while (ip + match_len < in_len - 5 && in[ref + match_len] == in[ip + match_len]) {
                match_len++;
            }

            // Output literals
            int lit_len = ip - anchor;
            int token = (lit_len >= 15 ? 15 : lit_len) << 4;
            int m_len = match_len - 4;
            token |= (m_len >= 15 ? 15 : m_len);

            out[op++] = token;
            if (lit_len >= 15) {
                int l = lit_len - 15;
                while (l >= 255) { out[op++] = 255; l -= 255; }
                out[op++] = l;
            }
            if (lit_len > 0) {
                memcpy(out + op, in + anchor, lit_len);
                op += lit_len;
            }

            // Output match offset
            int offset = ip - ref;
            out[op++] = offset & 0xFF;
            out[op++] = (offset >> 8) & 0xFF;

            if (m_len >= 15) {
                int l = m_len - 15;
                while (l >= 255) { out[op++] = 255; l -= 255; }
                out[op++] = l;
            }

            ip += match_len;
            anchor = ip;
        } else {
            ip++;
        }
    }

    // Output remaining literals
    int lit_len = in_len - anchor;
    int token = (lit_len >= 15 ? 15 : lit_len) << 4;
    out[op++] = token;
    if (lit_len >= 15) {
        int l = lit_len - 15;
        while (l >= 255) { out[op++] = 255; l -= 255; }
        out[op++] = l;
    }
    memcpy(out + op, in + anchor, lit_len);
    op += lit_len;

    return op;
}

int main() {
    return 0;
}
EOF
gcc -O3 mylz4.c -o mylz4_test"}

