{"command":"cat << 'EOF' > mylz4_test_decomp.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

int decompress_block(const uint8_t* in, int in_len, uint8_t* out, int max_out_len) {
    int i = 0;
    int o = 0;
    while (i < in_len) {
        uint8_t token = in[i++];

        int lit_len = token >> 4;
        if (lit_len == 15) {
            while (i < in_len && in[i] == 255) { lit_len += 255; i++; }
            if (i < in_len) lit_len += in[i++];
        }

        if (o + lit_len > max_out_len) return -1;
        memcpy(out + o, in + i, lit_len);
        i += lit_len; o += lit_len;

        if (i >= in_len) break;

        uint16_t offset = in[i] | (in[i+1] << 8); i += 2;

        int match_len = (token & 0x0F) + 4;
        if (match_len == 19) {
            while (i < in_len && in[i] == 255) { match_len += 255; i++; }
            if (i < in_len) match_len += in[i++];
        }

        if (o + match_len > max_out_len) return -1;
        for (int m = 0; m < match_len; m++) { out[o] = out[o - offset]; o++; }
    }
    return o;
}

int main() {
    FILE *f = fopen("assets/sample.txt.lz4", "rb");
    if (!f) return 1;
    uint8_t header[128];
    fread(header, 1, 7, f);
    if (*(uint32_t*)header != 0x184D2204) return 1;
    uint8_t flg = header[4];
    if ((flg >> 3) & 1) fseek(f, 8, SEEK_CUR); // content size
    if ((flg >> 0) & 1) fseek(f, 4, SEEK_CUR); // dict id

    while (1) {
        uint32_t size;
        if (fread(&size, 1, 4, f) != 4) break;
        if (size == 0) break;

        int uncompressed = size & 0x80000000;
        size &= 0x7FFFFFFF;

        uint8_t* in = malloc(size);
        fread(in, 1, size, f);

        if (uncompressed) {
            fwrite(in, 1, size, stdout);
        } else {
            uint8_t* out = malloc(4*1024*1024);
            int out_len = decompress_block(in, size, out, 4*1024*1024);
            if (out_len > 0) fwrite(out, 1, out_len, stdout);
            free(out);
        }
        free(in);

        if ((flg >> 4) & 1) fseek(f, 4, SEEK_CUR); // block checksum
    }
    if ((flg >> 2) & 1) fseek(f, 4, SEEK_CUR); // content checksum
    fclose(f);
    return 0;
}
EOF
