    int i = 0;
    int o = 0;
    while (i < in_len) {
        uint8_t token = in[i++];
        int lit_len = token >> 4;
        if (lit_len == 15) {
            while (i < in_len && in[i] == 255) { lit_len += 255; i++; }
            if (i < in_len) lit_len += in[i++];
        }
        if (o + lit_len > max_out_len) return -1;
        memcpy(out + o, in + i, lit_len);
        i += lit_len; o += lit_len;
        if (i >= in_len) break;
        uint16_t offset = in[i] | (in[i+1] << 8); i += 2;
        int match_len = (token & 0x0F) + 4;
        if (match_len == 19) {
            while (i < in_len && in[i] == 255) { match_len += 255; i++; }
            if (i < in_len) match_len += in[i++];
        }
        if (o + match_len > max_out_len) return -1;
        for (int m = 0; m < match_len; m++) { out[o] = out[o - offset]; o++; }
    }
    return o;
}

