    uint8_t header[] = {0x04, 0x22, 0x4D, 0x18, 0x60, 0x70, 0x73};
    fwrite(header, 1, 7, fout);
    unsigned long long total_in = 0;
    unsigned long long total_out = 7;

    uint8_t* buf = malloc(4*1024*1024);
    while (1) {
        int r = fread(buf, 1, 4*1024*1024, fin);
        if (r <= 0) break;
        total_in += r;
        uint32_t size = r | 0x80000000;
        fwrite(&size, 1, 4, fout);
        fwrite(buf, 1, r, fout);
        total_out += 4 + r;
    }
    free(buf);
    uint32_t end_mark = 0;
