    uint8_t flg = header[4];
    if ((flg >> 3) & 1) fseek(fin, 8, SEEK_CUR);
    if ((flg >> 0) & 1) fseek(fin, 4, SEEK_CUR);

    unsigned long long total_out = 0;
    while (1) {
