                    } else {
                        snprintf(out_buf, sizeof(out_buf), "%s.lz4", inputs[i]); // Default handling for unrecognized?
                        // actually skip
                        continue;
                    }
                    process_file(inputs[i], out_buf, false);
                }
            }
        }
    } else {
        bool compress = !opt_decompress;
        if (!opt_force_compress && !opt_decompress) {
            int len = strlen(inputs[0]);
            if (len > 4 && strcmp(inputs[0] + len - 4, ".lz4") == 0) compress = false;
        }

        char out_buf[1024];
        if (!output && !opt_stdout && !opt_test) {
            if (compress) {
                snprintf(out_buf, sizeof(out_buf), "%s.lz4", inputs[0]);
                output = out_buf;
            } else {
                int len = strlen(inputs[0]);
                if (len > 4 && strcmp(inputs[0] + len - 4, ".lz4") == 0) {
                    snprintf(out_buf, len - 3, "%s", inputs[0]);
                    output = out_buf;
                } else {
                    fprintf(stderr, "Cannot determine an output filename \nIncorrect parameters\n");
                    print_help(argv[0]);
                    exit(1);
                }
            }
        }
        process_file(inputs[0], output, compress);
    }

    return 0;
}
