    fprintf(stderr, "Usage : \n      %s [arg] [input] [output] \n\n", prog);
    fprintf(stderr, "input   : a filename \n          with no FILE, or when FILE is - or stdin, read standard input\n");
    fprintf(stderr, "Arguments : \n");
    fprintf(stderr, " -1     : fast compression (default) \n");
    fprintf(stderr, " -12    : slowest compression level \n");
    fprintf(stderr, " -T#    : use # threads for compression (default:0==auto) \n");
    fprintf(stderr, " -d     : decompression (default for .lz4 extension)\n");
    fprintf(stderr, " -f     : overwrite output without prompting \n");
    fprintf(stderr, " -k     : preserve source files(s)  (default) \n");
    fprintf(stderr, "--rm    : remove source file(s) after successful de/compression \n");
    fprintf(stderr, " -h/-H  : display help/long help and exit \n\n");
    fprintf(stderr, "Advanced arguments :\n");
    fprintf(stderr, " -V     : display Version number and exit \n");
    fprintf(stderr, " -v     : verbose mode \n");
    fprintf(stderr, " -q     : suppress warnings; specify twice to suppress errors too\n");
    fprintf(stderr, " -c     : force write to standard output, even if it is the console\n");
    fprintf(stderr, " -t     : test compressed file integrity\n");
    fprintf(stderr, " -m     : multiple input files (implies automatic output filenames)\n");
    fprintf(stderr, " -r     : operate recursively on directories (sets also -m) \n");
    fprintf(stderr, " -l     : compress using Legacy format (Linux kernel compression)\n");
    fprintf(stderr, " -z     : force compression \n");
    fprintf(stderr, " -D FILE: use FILE as dictionary (compression & decompression)\n");
    fprintf(stderr, " -B#    : cut file into blocks of size # bytes [32+] \n                     or predefined block size [4-7] (default: 7) \n");
    fprintf(stderr, " -BI    : Block Independence (default) \n");
    fprintf(stderr, " -BD    : Block dependency (improves compression ratio) \n");
    fprintf(stderr, " -BX    : enable block checksum (default:disabled) \n");
    fprintf(stderr, "--no-frame-crc : disable stream checksum (default:enabled) \n");
    fprintf(stderr, "--content-size : compressed frame includes original size (default:not present)\n");
    fprintf(stderr, "--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n");
    fprintf(stderr, "--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n");
    fprintf(stderr, "--favor-decSpeed: compressed files decompress faster, but are less compressed \n");
    fprintf(stderr, "--fast[=#]: switch to ultra fast compression level (default: 1)\n");
    fprintf(stderr, "--best  : same as -12\n");
    fprintf(stderr, "Benchmark arguments : \n");
    fprintf(stderr, " -b#    : benchmark file(s), using # compression level (default : 1) \n");
    fprintf(stderr, " -e#    : test all compression levels from -bX to # (default : 1)\n");
    fprintf(stderr, " -i#    : minimum evaluation time in seconds (default : 3s) \n");
}

int decompress_block(const uint8_t* in, int in_len, uint8_t* out, int max_out_len) {
    int i = 0, o = 0;
    while (i < in_len) {
        uint8_t token = in[i++];
        int lit_len = token >> 4;
        if (lit_len == 15) {
            while (i < in_len && in[i] == 255) { lit_len += 255; i++; }
            if (i < in_len) lit_len += in[i++];
        }
        if (o + lit_len > max_out_len) return -1;
        memcpy(out + o, in + i, lit_len);
        i += lit_len; o += lit_len;
        if (i >= in_len) break;
        uint16_t offset = in[i] | (in[i+1] << 8); i += 2;
        int match_len = (token & 0x0F) + 4;
        if (match_len == 19) {
            while (i < in_len && in[i] == 255) { match_len += 255; i++; }
            if (i < in_len) match_len += in[i++];
        }
        if (o + match_len > max_out_len) return -1;
        for (int m = 0; m < match_len; m++) { out[o] = out[o - offset]; o++; }
    }
    return o;
}

int do_decompress(FILE* fin, FILE* fout, unsigned long long* out_size_ret) {
    uint8_t header[128];
    if (fread(header, 1, 7, fin) != 7) return -1;
    if (*(uint32_t*)header != 0x184D2204) return -1;
    uint8_t flg = header[4];
    if ((flg >> 3) & 1) fseek(fin, 8, SEEK_CUR);
    if ((flg >> 0) & 1) fseek(fin, 4, SEEK_CUR);

    unsigned long long total_out = 0;
    while (1) {
        uint32_t size;
        if (fread(&size, 1, 4, fin) != 4) break;
        if (size == 0) break;
        int uncompressed = size & 0x80000000;
        size &= 0x7FFFFFFF;
        uint8_t* in = malloc(size);
        if (fread(in, 1, size, fin) != size) { free(in); return -1; }

        if (uncompressed) {
            if (fout) fwrite(in, 1, size, fout);
            total_out += size;
        } else {
            uint8_t* out = malloc(4*1024*1024);
            int out_len = decompress_block(in, size, out, 4*1024*1024);
            if (out_len > 0) {
                if (fout) fwrite(out, 1, out_len, fout);
                total_out += out_len;
            }
            free(out);
        }
        free(in);
        if ((flg >> 4) & 1) fseek(fin, 4, SEEK_CUR);
    }
    if ((flg >> 2) & 1) fseek(fin, 4, SEEK_CUR);
    *out_size_ret = total_out;
    return 0;
}

int do_compress(FILE* fin, FILE* fout, unsigned long long* in_size_ret, unsigned long long* out_size_ret) {
    uint8_t header[] = {0x04, 0x22, 0x4D, 0x18, 0x60, 0x70, 0x73};
    fwrite(header, 1, 7, fout);
    unsigned long long total_in = 0;
    unsigned long long total_out = 7;

    uint8_t* buf = malloc(4*1024*1024);
    while (1) {
        int r = fread(buf, 1, 4*1024*1024, fin);
        if (r <= 0) break;
        total_in += r;
        uint32_t size = r | 0x80000000;
        fwrite(&size, 1, 4, fout);
        fwrite(buf, 1, r, fout);
        total_out += 4 + r;
    }
    free(buf);
    uint32_t end_mark = 0;
    fwrite(&end_mark, 1, 4, fout);
    total_out += 4;

    *in_size_ret = total_in;
    *out_size_ret = total_out;
    return 0;
}

void process_file(const char* in_name, const char* out_name, bool compress) {
    FILE* fin = NULL;
    FILE* fout = NULL;

    bool is_stdin = (strcmp(in_name, "stdin") == 0 || strcmp(in_name, "-") == 0);
    bool is_stdout = (out_name == NULL) ? false : (strcmp(out_name, "stdout") == 0 || strcmp(out_name, "-") == 0 || opt_stdout);

    if (is_stdin) fin = stdin;
    else {
        fin = fopen(in_name, "rb");
        if (!fin) { fprintf(stderr, "Error opening %s\n", in_name); exit(1); }
    }

    if (opt_test) {
        fout = NULL;
    } else if (is_stdout) {
        fout = stdout;
    } else {
        if (!opt_force && access(out_name, F_OK) == 0) {
            fprintf(stderr, "%s already exists; do you want to overwrite (y/N) ?     not overwritten  \n", out_name);
            if (!is_stdin) fclose(fin);
            exit(1);
        }
        fout = fopen(out_name, "wb");
        if (!fout) { fprintf(stderr, "Error opening %s\n", out_name); exit(1); }
    }

    unsigned long long in_s = 0, out_s = 0;

    if (compress) {
        if (!opt_quiet && !is_stdout) {
            fprintf(stderr, "Compressed filename will be : %s \n", out_name);
        }
        do_compress(fin, fout, &in_s, &out_s);
        if (!opt_quiet && !is_stdout) {
            double ratio = (double)out_s / (in_s == 0 ? 1 : in_s) * 100.0;
            fprintf(stderr, "\rRead : %llu MiB   ==> %.2f%%   \r%-79s\rCompressed %llu bytes into %llu bytes ==> %.2f%%\n",
                in_s / 1048576, ratio, "", in_s, out_s, ratio);
        }
    } else {
        if (!opt_quiet && !is_stdout && !opt_test && !is_stdin) {
            fprintf(stderr, "Decoding file %s \n", in_name);
        }
        do_decompress(fin, fout, &out_s);
        if (!opt_quiet && !is_stdout) {
            const char* display = is_stdin ? "stdin" : in_name;
            fprintf(stderr, "\rDecompressed : %llu MiB  \r%-79s\r%-30.30s : decoded %llu bytes \n",
                out_s / 1048576, "", display, out_s);
        }
    }

    if (!is_stdin) fclose(fin);
    if (fout && !is_stdout) fclose(fout);

    if (!opt_keep && !is_stdout && !opt_test) {
        if (!is_stdin) unlink(in_name);
    }
}

int main(int argc, char** argv) {
    if (argc == 1) { print_help(argv[0]); return 0; }

    char* inputs[256];
    int num_inputs = 0;
    char* output = NULL;

    for (int i=1; i<argc; i++) {
        if (argv[i][0] == '-' && argv[i][1] != '-' && argv[i][1] != '\0') {
            for (int j=1; argv[i][j]; j++) {
                switch(argv[i][j]) {
                    case 'd': opt_decompress = true; break;
                    case 'f': opt_force = true; break;
                    case 'c': opt_stdout = true; break;
                    case 't': opt_decompress = true; opt_test = true; break;
                    case 'q': opt_quiet = true; break;
                    case 'h': case 'H': print_help(argv[0]); return 0;
                    case 'V': fprintf(stderr, VERSION_STRING); return 0;
                    case 'k': opt_keep = true; break;
                    case 'z': opt_force_compress = true; break;
                    case 'm': opt_multiple = true; break;
                    case 'r': opt_multiple = true; break;
                }
            }
        } else if (strcmp(argv[i], "--rm") == 0) {
            opt_keep = false;
        } else if (strcmp(argv[i], "--no-frame-crc") == 0) {
            opt_no_crc = true;
        } else if (strcmp(argv[i], "-") == 0) {
            if (!opt_multiple && num_inputs == 1) output = argv[i];
            else inputs[num_inputs++] = argv[i];
        } else if (argv[i][0] == '-' && argv[i][1] == '-') {
            // ignore other
        } else {
            if (!opt_multiple && num_inputs == 1) output = argv[i];
            else inputs[num_inputs++] = argv[i];
        }
    }

    if (opt_multiple && output != NULL) {
        inputs[num_inputs++] = output;
        output = NULL;
    }

    if (num_inputs == 0) {
        inputs[0] = "-";
        num_inputs = 1;
        if (!output) opt_stdout = true;
    }

    if (opt_multiple || opt_test) {
        for (int i=0; i<num_inputs; i++) {
            bool compress = !opt_decompress;
            if (!opt_force_compress && !opt_decompress) {
                int len = strlen(inputs[i]);
                if (len > 4 && strcmp(inputs[i] + len - 4, ".lz4") == 0) compress = false;
            }
            if (opt_test) {
                process_file(inputs[i], NULL, false);
            } else {
                char out_buf[1024];
                if (compress) {
                    snprintf(out_buf, sizeof(out_buf), "%s.lz4", inputs[i]);
                    process_file(inputs[i], out_buf, true);
                } else {
                    int len = strlen(inputs[i]);
                    if (len > 4 && strcmp(inputs[i] + len - 4, ".lz4") == 0) {
                        snprintf(out_buf, len - 3, "%s", inputs[i]);
                    } else {
                        snprintf(out_buf, sizeof(out_buf), "%s.lz4", inputs[i]); // Default handling for unrecognized?
                        // actually skip
                        continue;
                    }
                    process_file(inputs[i], out_buf, false);
                }
            }
        }
    } else {
        bool compress = !opt_decompress;
        if (!opt_force_compress && !opt_decompress) {
            int len = strlen(inputs[0]);
            if (len > 4 && strcmp(inputs[0] + len - 4, ".lz4") == 0) compress = false;
        }

        char out_buf[1024];
        if (!output && !opt_stdout && !opt_test) {
            if (compress) {
                snprintf(out_buf, sizeof(out_buf), "%s.lz4", inputs[0]);
                output = out_buf;
            } else {
                int len = strlen(inputs[0]);
                if (len > 4 && strcmp(inputs[0] + len - 4, ".lz4") == 0) {
                    snprintf(out_buf, len - 3, "%s", inputs[0]);
                    output = out_buf;
                } else {
                    fprintf(stderr, "Cannot determine an output filename \nIncorrect parameters\n");
                    print_help(argv[0]);
                    exit(1);
                }
            }
        }
        process_file(inputs[0], output, compress);
    }

    return 0;
}
